namespace ghidra.graph;



using org.apache.commons.text;

using ghidra.program.model.symbol;
using ghidra.service.graph;

/**
 * Defines a common set of vertex and edge types {@link GraphType} for program code and data flow
 * graphs. Each specific type of program graph will use a subclass to specifically identify the
 * graph type.
 */

public abstract class ProgramGraphType : GraphType {
	private static Map<RefType, string> refTypeToEdgeTypeMap = new();
	private static List<string> vertexTypes = new();
	private static List<string> edgeTypes = new();
	//@formatter:off
	
	// Vertex Types
	public static readonly string BODY = vertex("Body");
	public static readonly string ENTRY = vertex("Entry");
	public static readonly string EXIT = vertex("Exit");
	public static readonly string SWITCH = vertex("Switch");
	public static readonly string EXTERNAL = vertex("External");
	public static readonly string BAD = vertex("Bad");
	public static readonly string INSTRUCTION = vertex("Instruction");
	public static readonly string DATA = vertex("Data");
	public static readonly string ENTRY_NEXUS = vertex("Entry-Nexus");
	public static readonly string STACK = vertex("Stack");
	
	// Edge Types - Flow
	public static readonly string ENTRY_EDGE = edge("Entry");  // This edge if for adding an "Entry Nexus" Vertex
	public static readonly string FALL_THROUGH = edge(map(RefType.FALL_THROUGH));
	public static readonly string UNCONDITIONAL_JUMP = edge(map(RefType.UNCONDITIONAL_JUMP));
	public static readonly string UNCONDITIONAL_CALL = edge(map(RefType.UNCONDITIONAL_CALL));
	public static readonly string TERMINATOR = edge(map(RefType.TERMINATOR));
	public static readonly string JUMP_TERMINATOR = edge(map(RefType.JUMP_TERMINATOR));
	public static readonly string INDIRECTION = edge(map(RefType.INDIRECTION));

	public static readonly string CONDITIONAL_JUMP = edge(map(RefType.CONDITIONAL_JUMP));
	public static readonly string CONDITIONAL_CALL = edge(map(RefType.CONDITIONAL_CALL));
	public static readonly string CONDITIONAL_TERMINATOR = edge(map(RefType.CONDITIONAL_TERMINATOR));
	public static readonly string CONDITIONAL_CALL_TERMINATOR =edge(map(RefType.CONDITIONAL_CALL_TERMINATOR));
	
	public static readonly string COMPUTED_JUMP = edge(map(RefType.COMPUTED_JUMP));
	public static readonly string COMPUTED_CALL = edge(map(RefType.COMPUTED_CALL));
	public static readonly string COMPUTED_CALL_TERMINATOR = edge(map(RefType.COMPUTED_CALL_TERMINATOR));
	
	public static readonly string CONDITIONAL_COMPUTED_CALL = edge(map(RefType.CONDITIONAL_COMPUTED_CALL));
	public static readonly string CONDITIONAL_COMPUTED_JUMP =edge(map(RefType.CONDITIONAL_COMPUTED_JUMP));

	public static readonly string CALL_OVERRIDE_UNCONDITIONAL = edge(map(RefType.CALL_OVERRIDE_UNCONDITIONAL));
	public static readonly string JUMP_OVERRIDE_UNCONDITIONAL = edge(map(RefType.CALL_OVERRIDE_UNCONDITIONAL));
	public static readonly string CALLOTHER_OVERRIDE_CALL = edge(map(RefType.CALL_OVERRIDE_UNCONDITIONAL));
	public static readonly string CALLOTHER_OVERRIDE_JUMP = edge(map(RefType.CALL_OVERRIDE_UNCONDITIONAL));

	// Edge Types Data Refs
	public static readonly string READ = edge(map(RefType.READ));
	public static readonly string WRITE = edge(map(RefType.WRITE));
	public static readonly string READ_WRITE = edge(map(RefType.READ_WRITE));
	public static readonly string UNKNOWN_DATA = edge(map(RefType.DATA));
	public static readonly string EXTERNAL_REF = edge(map(RefType.EXTERNAL_REF));
	
	public static readonly string READ_INDIRECT = edge(map(RefType.READ_IND));
	public static readonly string WRITE_INDIRECT = edge(map(RefType.WRITE_IND));
	public static readonly string READ_WRITE_INDIRECT = edge(map(RefType.READ_WRITE_IND));
	public static readonly string DATA_INDIRECT = edge(map(RefType.DATA_IND));

	public static readonly string PARAM = edge(map(RefType.PARAM));
	public static readonly string THUNK = edge(map(RefType.THUNK));
	
	//@formatter:on

	protected ProgramGraphType(string name, string description) : base(name, description, vertexTypes, edgeTypes)
    {
	}

	private static string vertex(string vertexType) {
		vertexTypes.add(vertexType);
		return vertexType;
	}

	private static string edge(string edgeType) {
		edgeTypes.add(edgeType);
		return edgeType;
	}

	private static string map(RefType refType) {
		string edgeTypeName = fixup(refType.getName());
		refTypeToEdgeTypeMap.put(refType, edgeTypeName);
		return edgeTypeName;
	}

	private static string fixup(string name) {
		name = name.replace('_', ' ');
		return WordUtils.capitalizeFully(name);
	}

	public static string getEdgeType(RefType refType) {
		return refTypeToEdgeTypeMap.get(refType);
	}

	/* @Override */
	public string getOptionsName() {
		return "Program Graph Display Options";
	}

}
